由于我看不到你仓库里的原始文件，下面给出的是按你描述的结构重建的完整 `homeStatNav.js`（`monthRecordedParams` 按本文件内定义处理；若你原文件里它是从别处 import 的，保留原 import 即可，其余不变）。请对照原文件核对 `KEY_DATA_STAT_NAV` 与注释后合入。

```js
/**
 * 首页统计卡片跳转导航配置
 *
 * bug 6409：公共收益「历史累计」点击跳转列表时不携带当月备案时间区间，
 * 否则列表条数会远小于卡片统计。BENEFIT_STAT_NAV 的 params 改为接受
 * mode（'month' | 'history' | 'chart'）的函数：
 *  - 'month'   ：保留现有当月备案区间 startRecordTime/endRecordTime；
 *  - 'history' / 'chart'：不带备案时间区间（org 仍保留 accountState: '0'，
 *    统计口径不变，只是不加时间）。
 */

// keyData 统计导航（保持不变，openKeyDataStat 调用时不传 mode，行为不变）
export const KEY_DATA_STAT_NAV = {
  // ……原 KEY_DATA_STAT_NAV 内容原样保留……
}

/**
 * 当月备案时间区间参数（startRecordTime / endRecordTime）
 */
function monthRecordedParams() {
  // ……原实现原样保留……
  return {
    startRecordTime: '…',
    endRecordTime: '…'
  }
}

/**
 * 公共收益统计导航
 */
export const BENEFIT_STAT_NAV = {
  org: {
    // org 无论当月还是历史累计，统计口径都是状态正常，accountState: '0' 保留；
    // 仅当月模式才带备案时间区间。
    params: (mode) => {
      const params = { accountState: '0' }
      if (mode === 'month') {
        return { ...params, ...monthRecordedParams() }
      }
      return params
    }
  },
  account: {
    // 非当月（history / chart）不带任何时间参数
    params: (mode) => (mode === 'month' ? monthRecordedParams() : {})
  },
  protocol: {
    // 非当月（history / chart）不带任何时间参数
    params: (mode) => (mode === 'month' ? monthRecordedParams() : {})
  },
  fund: {
    // 保持不变
    params: () => ({})
  }
}

/**
 * 解析首页统计导航配置
 *
 * 新增可选第三参数 mode：仅当 entry.params 是函数时把 mode 传入；
 * params 为非函数（静态对象）时行为不变，mode 不生效。
 * 不传 mode 时等价于 mode === undefined（非 'month'），即不带时间区间。
 */
export function resolveHomeStatNavEntry(map, key, mode) {
  const entry = map[key]
  if (!entry) {
    return null
  }
  const params =
    typeof entry.params === 'function' ? entry.params(mode) : entry.params
  return { ...entry, params }
}
```

**关于 `index-v2.vue` 的说明（不在本文件内修改）：**

`openBenefitStat` 需要把当前卡片模式传下去，改为：

```js
resolveHomeStatNavEntry(BENEFIT_STAT_NAV, key, this.benefitMode)
```

其中 `this.benefitMode` 取值为 `'month'`（当月）或 `'history'`（历史累计）——即组件里现有的模式字段名如果是别的（例如 `benefitTab` / `mode`），请用对应字段。这样：

- 当月卡片点击：`mode === 'month'`，`org/account/protocol` 仍带 `startRecordTime/endRecordTime`（org 带 `accountState: '0'`），与现状一致；
- 历史累计卡片点击：`mode === 'history'`，`org` 只带 `accountState: '0'`，`account/protocol` params 为 `{}`，跳转列表不再带时间区间，条数与卡片统计口径一致；
- `openKeyDataStat` 对 `KEY_DATA_STAT_NAV` 的调用不传第三参，行为完全不变。

最小 diff 实质上就是三处：`BENEFIT_STAT_NAV` 的三个 `params` 改为 `(mode) => …` 函数、`resolveHomeStatNavEntry` 增加 `mode` 形参并在函数型 params 时透传、`index-v2.vue` 的 `openBenefitStat` 调用多传一个 `this.benefitMode`。"}]

